      button.type = "button";
      button.id = buttonId;
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", contentId);

      details.id = contentId;
      details.setAttribute("role", "region");
      details.setAttribute("aria-labelledby", buttonId);

      detailsContent.appendChild(createElement("p", "", answer));
      detailsInner.appendChild(detailsContent);
      details.appendChild(detailsInner);

      button.append(questionText, icon);
      button.addEventListener("click", () => {
        const isOpen = button.getAttribute("aria-expanded") === "true";
        button.setAttribute("aria-expanded", String(!isOpen));
        details.classList.toggle("is-open", !isOpen);
      });

      wrapper.append(button, details);
      return wrapper;
    };

