      const section = createElement("section", "hero");
      const eyebrow = createElement("div", "eyebrow", "Cat care essentials");
      const title = createElement("h1", "", "Frequently asked questions about cats");
      const text = createElement(
        "p",
        "",
        "A simple guide to some of the most common cat questions, presented in a clean accordion layout so you can scan quickly and expand the answers you need."
      );

      const list = createElement("div", "faq-list");
      faqs.forEach((item, index) => list.appendChild(FAQItem(item, index)));

      section.append(eyebrow, title, text, list);
      return section;
    };

    const App = () => {
      const shell = createElement("main", "page-shell");
      shell.appendChild(Hero());
      return shell;
    };

    document.getElementById("app").appendChild(App());
  </script>
