  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --panel: rgba(255, 255, 255, 0.88);
      --panel-border: rgba(15, 23, 42, 0.08);
      --text: #0f172a;
      --muted: #475569;
      --accent: #7c3aed;
      --accent-strong: #5b21b6;
      --shadow: 0 24px 60px rgba(15, 23, 42, 0.14);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.18), transparent 34%),
        radial-gradient(circle at top right, rgba(59, 130, 246, 0.14), transparent 28%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
    }

    .page-shell {
      width: min(960px, calc(100% - 32px));
      margin: 0 auto;
      padding: 56px 0 72px;
    }

    .hero {
      padding: 40px;
      border: 1px solid var(--panel-border);
      border-radius: 32px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 8px 14px;
      border-radius: 999px;
      background: rgba(124, 58, 237, 0.1);
      color: var(--accent-strong);
      font-size: 0.82rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    h1 {
      margin: 18px 0 14px;
      font-size: clamp(2.25rem, 5vw, 4rem);
      line-height: 1.02;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 60ch;
      color: var(--muted);
      font-size: 1.06rem;
      line-height: 1.7;
    }

    .faq-list {
      margin-top: 28px;
      display: grid;
      gap: 16px;
    }

    .example {
      border: 1px solid rgba(124, 58, 237, 0.12);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.94);
      box-shadow: 0 14px 36px rgba(15, 23, 42, 0.08);
      overflow: hidden;
    }

    .question {
      width: 100%;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 22px 24px;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
      text-align: left;
      cursor: pointer;
    }

    .question:hover {
      background: rgba(124, 58, 237, 0.04);
    }

    .question:focus-visible {
      outline: 3px solid rgba(124, 58, 237, 0.3);
      outline-offset: -3px;
    }

    .question-text {
      font-size: 1.02rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .icon {
      flex: 0 0 auto;
      width: 34px;
      height: 34px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      background: rgba(124, 58, 237, 0.1);
      color: var(--accent-strong);
      font-size: 1.25rem;
      transition: transform 180ms ease, background-color 180ms ease;
    }

    .question[aria-expanded="true"] .icon {
      transform: rotate(45deg);
      background: rgba(124, 58, 237, 0.18);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
      background: linear-gradient(180deg, rgba(124, 58, 237, 0.03), rgba(59, 130, 246, 0.04));
    }

    .details.is-open {
      grid-template-rows: 1fr;
    }

    .details-inner {
      overflow: hidden;
    }

    .details-content {
      padding: 0 24px 24px;
      color: var(--muted);
      line-height: 1.75;
    }

    .details-content p {
      margin: 0;
    }

    @media (max-width: 640px) {
      .page-shell {
        width: min(100% - 20px, 960px);
        padding: 24px 0 40px;
      }

      .hero {
        padding: 24px;
        border-radius: 24px;
      }

      .question,
      .details-content {
        padding-left: 18px;
        padding-right: 18px;
      }

      .question {
        padding-top: 18px;
        padding-bottom: 18px;
      }

      .details-content {
        padding-bottom: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const faqs = [
      {
        question: "Why do cats purr?",
        answer: "Cats often purr when they feel safe, content, or bonded with people, but they can also purr to soothe themselves when stressed or recovering. It is a versatile sound that can signal comfort, communication, and self-regulation."
      },
      {
        question: "How much sleep do cats need?",
        answer: "Most cats sleep between 12 and 16 hours a day, with kittens and senior cats often sleeping even more. Their rest comes in bursts, so a cat may seem active for short stretches and then disappear for another long nap."
      },
      {
        question: "Do indoor cats still need playtime?",
        answer: "Yes. Indoor cats need daily play to exercise their bodies and satisfy hunting instincts. Wand toys, puzzle feeders, climbing spots, and short interactive sessions help reduce boredom and keep them mentally engaged."
      },
      {
        question: "Why do cats knead with their paws?",
        answer: "Kneading starts in kittenhood while nursing and often carries into adulthood as a comforting behavior. Cats may knead soft blankets, beds, or laps when they feel relaxed, secure, and attached to their environment."
      },
      {
        question: "What is the best way to help a cat adjust to a new home?",
        answer: "Start with one quiet room stocked with food, water, litter, a hiding spot, and familiar scents. Let the cat explore at its own pace, keep routines consistent, and gradually open up more space as confidence grows."
      }
    ];

    const createElement = (tag, className, content) => {
      const element = document.createElement(tag);
      if (className) {
        element.className = className;
      }
      if (typeof content === "string") {
        element.textContent = content;
      }
      return element;
    };

    const FAQItem = ({ question, answer }, index) => {
      const wrapper = createElement("div", "example");
      const button = createElement("button", "question");
      const details = createElement("div", "details");
      const detailsInner = createElement("div", "details-inner");
      const detailsContent = createElement("div", "details-content");
      const questionText = createElement("span", "question-text", question);
      const icon = createElement("span", "icon", "+");

      const contentId = `faq-panel-${index}`;
      const buttonId = `faq-button-${index}`;

      button.type = "button";
      button.id = buttonId;
      button.setAttribute("aria-expanded", "false");
      button.setAttribute("aria-controls", contentId);

      details.id = contentId;
      details.setAttribute("role", "region");
      details.setAttribute("aria-labelledby", buttonId);

      detailsContent.appendChild(createElement("p", "", answer));
      detailsInner.appendChild(detailsContent);
      details.appendChild(detailsInner);

      button.append(questionText, icon);
      button.addEventListener("click", () => {
        const isOpen = button.getAttribute("aria-expanded") === "true";
        button.setAttribute("aria-expanded", String(!isOpen));
        details.classList.toggle("is-open", !isOpen);
      });

      wrapper.append(button, details);
      return wrapper;
    };

    const Hero = () => {
      const section = createElement("section", "hero");
      const eyebrow = createElement("div", "eyebrow", "Cat care essentials");
      const title = createElement("h1", "", "Frequently asked questions about cats");
      const text = createElement(
        "p",
        "",
        "A simple guide to some of the most common cat questions, presented in a clean accordion layout so you can scan quickly and expand the answers you need."
      );

      const list = createElement("div", "faq-list");
      faqs.forEach((item, index) => list.appendChild(FAQItem(item, index)));

      section.append(eyebrow, title, text, list);
      return section;
    };

    const App = () => {
      const shell = createElement("main", "page-shell");
      shell.appendChild(Hero());
      return shell;
    };

    document.getElementById("app").appendChild(App());
  </script>
</body>
</html>
